import { useEffect } from 'react'
import { useQuery } from 'react-query'
import { useAuthStore } from '../stores/authStore'
import { api } from '../stores/authStore'
import {
  FileText,
  MapPin,
  Users,
  Brush,
  TrendingUp,
  Calendar,
  AlertCircle
} from 'lucide-react'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area
} from 'recharts'

const COLORS = ['#2563eb', '#60a5fa', '#93c5fd', '#1d4ed8', '#3b82f6']

const KPICard = ({ title, value, icon: Icon, color, subtitle }) => (
  <div className="bg-white/5 border border-white/10 rounded-2xl p-6 hover:bg-white/10 transition-all group">
    <div className="flex items-start justify-between mb-4">
      <div className={`p-3 rounded-xl ${color} bg-opacity-10`}>
        <Icon className={`w-6 h-6 ${color.replace('bg-', 'text-')}`} />
      </div>
      <TrendingUp className="w-5 h-5 text-slate-600 group-hover:text-ARMA -light transition-colors" />
    </div>
    <h3 className="text-3xl font-black text-white">{value}</h3>
    <p className="text-sm text-slate-400 mt-1">{title}</p>
    {subtitle && <p className="text-xs text-slate-600 mt-1">{subtitle}</p>}
  </div>
)

export default function Dashboard() {
  const { user } = useAuthStore()
  const role = user?.role || 'client'

  // Fetch stats
  const { data: stats, isLoading: statsLoading } = useQuery(
    'dashboard-stats',
    () => api.get('/dashboard/stats').then(res => res.data),
    { enabled: role !== 'client' }
  )

  // Fetch client stats
  const { data: clientStats, isLoading: clientStatsLoading } = useQuery(
    'client-stats',
    () => api.get('/dashboard/client-stats').then(res => res.data),
    { enabled: role === 'client' }
  )

  // Fetch recent reports
  const { data: recentReports } = useQuery(
    'recent-reports',
    () => api.get('/dashboard/recent-reports').then(res => res.data),
    { enabled: role !== 'client' }
  )

  const isLoading = statsLoading || clientStatsLoading

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-ARMA -blue" />
      </div>
    )
  }

  // Client Dashboard
  if (role === 'client') {
    return (
      <div className="space-y-6">
        <div className="bg-gradient-to-r from-ARMA -blue/20 to-ARMA -light/10 border border-ARMA -blue/30 rounded-3xl p-8">
          <h1 className="text-3xl font-black text-white">🏢 Mes Rapports</h1>
          <p className="text-slate-400 mt-2">
            Station: <span className="text-ARMA -light font-semibold">{user?.client_code}</span>
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <KPICard
            title="Interventions totales"
            value={clientStats?.total_interventions || 0}
            icon={FileText}
            color="bg-blue-500"
            subtitle="Toutes périodes"
          />
          <KPICard
            title="Zones nettoyées"
            value={clientStats?.zones_cleaned || 0}
            icon={Brush}
            color="bg-emerald-500"
            subtitle={clientStats?.zones_list?.join(', ') || 'Aucune'}
          />
          <KPICard
            title="Ce mois-ci"
            value={clientStats?.this_month || 0}
            icon={Calendar}
            color="bg-amber-500"
            subtitle="Interventions"
          />
        </div>

        {clientStats?.last_intervention && (
          <div className="bg-white/5 border border-white/10 rounded-2xl p-6">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
              <AlertCircle className="w-5 h-5 text-ARMA -light" />
              Dernière Intervention
            </h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-slate-500">Date</p>
                <p className="text-white font-medium">
                  {new Date(clientStats.last_intervention).toLocaleDateString('fr-FR')}
                </p>
              </div>
              <div>
                <p className="text-sm text-slate-500">Zone</p>
                <p className="text-white font-medium">{clientStats.last_zone}</p>
              </div>
            </div>
          </div>
        )}
      </div>
    )
  }

  // Admin/Employer Dashboard
  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-ARMA -blue/20 to-ARMA -light/10 border border-ARMA -blue/30 rounded-3xl p-8">
        <h1 className="text-3xl font-black text-white">
          {role === 'admin' ? '🛡️ Tableau de Bord Admin' : '👷 Mon Tableau de Bord'}
        </h1>
        <p className="text-slate-400 mt-2">
          {role === 'admin' 
            ? 'Accès complet — toutes les stations'
            : `Stations: ${user?.assigned_stations?.join(', ') || 'Toutes'}`
          }
        </p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
        <KPICard
          title="Rapports"
          value={stats?.total_reports || 0}
          icon={FileText}
          color="bg-blue-500"
        />
        <KPICard
          title="Stations"
          value={stats?.total_stations || 0}
          icon={MapPin}
          color="bg-emerald-500"
        />
        <KPICard
          title="Agents"
          value={stats?.total_agents || 0}
          icon={Users}
          color="bg-amber-500"
        />
        <KPICard
          title="Zones"
          value={stats?.total_zones || 0}
          icon={Brush}
          color="bg-purple-500"
        />
        <KPICard
          title="Ce mois"
          value={stats?.reports_this_month || 0}
          icon={Calendar}
          color="bg-red-500"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Bar Chart - By City */}
        <div className="bg-white/5 border border-white/10 rounded-2xl p-6">
          <h3 className="text-lg font-bold text-white mb-4">📈 Interventions par Ville</h3>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={stats?.reports_by_city || []}>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
              <XAxis dataKey="city" tick={{ fill: '#64748b', fontSize: 12 }} />
              <YAxis tick={{ fill: '#64748b', fontSize: 12 }} />
              <Tooltip 
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #2563eb', borderRadius: '8px' }}
                labelStyle={{ color: '#fff' }}
              />
              <Bar dataKey="count" fill="#2563eb" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Pie Chart - By Zone */}
        <div className="bg-white/5 border border-white/10 rounded-2xl p-6">
          <h3 className="text-lg font-bold text-white mb-4">🍩 Répartition par Zone</h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={stats?.reports_by_zone || []}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={100}
                paddingAngle={5}
                dataKey="count"
                nameKey="zone"
              >
                {(stats?.reports_by_zone || []).map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #2563eb', borderRadius: '8px' }}
              />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Monthly Trend */}
      <div className="bg-white/5 border border-white/10 rounded-2xl p-6">
        <h3 className="text-lg font-bold text-white mb-4">📅 Évolution Mensuelle</h3>
        <ResponsiveContainer width="100%" height={250}>
          <AreaChart data={stats?.monthly_trend || []}>
            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
            <XAxis dataKey="month" tick={{ fill: '#64748b', fontSize: 12 }} />
            <YAxis tick={{ fill: '#64748b', fontSize: 12 }} />
            <Tooltip 
              contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #2563eb', borderRadius: '8px' }}
            />
            <Area 
              type="monotone" 
              dataKey="count" 
              stroke="#2563eb" 
              fill="#2563eb" 
              fillOpacity={0.1}
              strokeWidth={2}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Top Agents */}
      <div className="bg-white/5 border border-white/10 rounded-2xl p-6">
        <h3 className="text-lg font-bold text-white mb-4">🏆 Classement des Agents</h3>
        <div className="space-y-3">
          {(stats?.top_agents || []).map((agent, index) => (
            <div 
              key={agent.agent}
              className="flex items-center gap-4 p-3 rounded-xl bg-white/5 hover:bg-white/10 transition-all"
            >
              <div className={`
                w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold
                ${index === 0 ? 'bg-yellow-500/20 text-yellow-400' :
                  index === 1 ? 'bg-slate-400/20 text-slate-300' :
                  index === 2 ? 'bg-orange-600/20 text-orange-400' :
                  'bg-white/10 text-slate-400'}
              `}>
                {index + 1}
              </div>
              <div className="flex-1">
                <p className="text-white font-medium">{agent.agent}</p>
              </div>
              <div className="text-right">
                <p className="text-ARMA -light font-bold">{agent.interventions}</p>
                <p className="text-xs text-slate-500">interventions</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}
